#!/usr/bin/env python3
"""Deterministic validator for a fact-check run.

Validates the machine contract (artifacts/verdict.json) against the frozen
input claim and the human deliverable (artifacts/report.md). Any violation
exits non-zero so the pipeline halts before downstream use.

Checks performed:
  1. verdict.json is fully parseable JSON (NaN/Infinity rejected).
  2. Structural contract: required keys, types, enums, ranges, URL syntax,
     sha256 format, no unknown keys.
  3. Provenance anchor: verdict.claim equals the frozen input claim exactly,
     and verdict.claim_sha256 equals the frozen SHA-256.
  4. Verdict / evidence consistency (coverage of the claimed relation).
  5. report.md exists, is non-empty, and reflects the verdict and claim.
"""
import hashlib
import json
import pathlib
import re
import sys

URL_RE = re.compile(r"^https?://\S+$")
SHA_RE = re.compile(r"^[0-9a-f]{64}$")
VERDICTS = {"supported", "refuted", "partially_supported", "unverified"}
RELATIONS = {"supports", "refutes", "context"}

errors: list[str] = []


def fail(msg: str) -> None:
    errors.append(msg)


def reject_constant(name: str):
    def _raise(value):
        raise ValueError(f"non-finite constant {name!r} in JSON: {value}")

    return _raise


def load_json(path: pathlib.Path):
    try:
        raw = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        fail(f"missing file: {path}")
        return None
    try:
        return json.loads(raw, parse_constant=reject_constant)
    except ValueError as exc:
        fail(f"invalid JSON in {path}: {exc}")
        return None


def check_structure(v: dict) -> None:
    required = {
        "claim": str,
        "claim_sha256": str,
        "verdict": str,
        "confidence": (int, float),
        "summary": str,
        "evidence": list,
        "caveats": list,
    }
    allowed = set(required)
    extra = set(v) - allowed
    if extra:
        fail(f"verdict.json has unknown keys: {sorted(extra)}")
    for key, typ in required.items():
        if key not in v:
            fail(f"verdict.json missing required key: {key}")
            continue
        if not isinstance(v[key], typ) or isinstance(v[key], bool):
            fail(f"verdict.json key {key!r} has wrong type: {type(v[key]).__name__}")
    if v.get("verdict") not in VERDICTS:
        fail(f"verdict not in {sorted(VERDICTS)}: {v.get('verdict')!r}")
    conf = v.get("confidence")
    if isinstance(conf, (int, float)) and not isinstance(conf, bool):
        if not (0 <= conf <= 1):
            fail(f"confidence out of range [0,1]: {conf!r}")
    sha = v.get("claim_sha256")
    if isinstance(sha, str) and not SHA_RE.match(sha):
        fail(f"claim_sha256 is not a 64-char lowercase hex digest: {sha!r}")
    if isinstance(v.get("claim"), str) and v["claim"].strip() == "":
        fail("verdict.claim is empty")
    if isinstance(v.get("summary"), str) and v["summary"].strip() == "":
        fail("verdict.summary is empty")

    evidence = v.get("evidence")
    if isinstance(evidence, list):
        for i, item in enumerate(evidence):
            if not isinstance(item, dict):
                fail(f"evidence[{i}] is not an object")
                continue
            iextra = set(item) - {"source_url", "source_title", "quote", "relation"}
            if iextra:
                fail(f"evidence[{i}] has unknown keys: {sorted(iextra)}")
            for key in ("source_url", "source_title", "quote", "relation"):
                if key not in item:
                    fail(f"evidence[{i}] missing key: {key}")
                elif not isinstance(item[key], str):
                    fail(f"evidence[{i}].{key} is not a string")
            url = item.get("source_url")
            if isinstance(url, str) and not URL_RE.match(url):
                fail(f"evidence[{i}].source_url is not an http(s) URL: {url!r}")
            if item.get("relation") not in RELATIONS:
                fail(f"evidence[{i}].relation not in {sorted(RELATIONS)}: {item.get('relation')!r}")
    caveats = v.get("caveats")
    if isinstance(caveats, list):
        for i, c in enumerate(caveats):
            if not isinstance(c, str):
                fail(f"caveats[{i}] is not a string")


def check_provenance(v: dict, frozen_claim: str | None, frozen_sha: str | None) -> None:
    if frozen_claim is None or frozen_sha is None:
        return
    if v.get("claim") != frozen_claim:
        fail("verdict.claim does NOT match the frozen input claim verbatim")
    if v.get("claim_sha256") != frozen_sha:
        fail("verdict.claim_sha256 does NOT match the frozen input SHA-256")


def check_consistency(v: dict) -> None:
    verdict = v.get("verdict")
    evidence = v.get("evidence") or []
    relations = {e.get("relation") for e in evidence if isinstance(e, dict)}
    if verdict == "supported" and "supports" not in relations:
        fail("verdict 'supported' requires at least one evidence item with relation 'supports'")
    if verdict == "refuted" and "refutes" not in relations:
        fail("verdict 'refuted' requires at least one evidence item with relation 'refutes'")
    if verdict == "partially_supported" and not relations:
        fail("verdict 'partially_supported' requires at least one evidence item")
    if verdict == "unverified" and evidence:
        # Unverified with evidence is allowed only if every item is context.
        if relations - {"context"}:
            fail("verdict 'unverified' may only cite evidence with relation 'context'")


def check_report(report_path: pathlib.Path, v: dict | None) -> None:
    try:
        text = report_path.read_text(encoding="utf-8")
    except FileNotFoundError:
        fail(f"missing human deliverable: {report_path}")
        return
    if text.strip() == "":
        fail(f"report is empty: {report_path}")
        return
    if v is None:
        return
    verdict = v.get("verdict")
    if isinstance(verdict, str) and verdict not in text:
        fail(f"report does not mention the verdict {verdict!r}")
    claim = v.get("claim")
    if isinstance(claim, str) and claim.strip():
        probe = claim.strip()[:40]
        if probe and probe not in text:
            fail("report does not reference the claim under review")


def main() -> int:
    out_dir = pathlib.Path("artifacts")
    verdict_path = out_dir / "verdict.json"
    report_path = out_dir / "report.md"
    frozen_claim_path = out_dir / "input_claim.txt"
    frozen_sha_path = out_dir / "input_claim.sha256"

    if not frozen_claim_path.exists() or not frozen_sha_path.exists():
        print("ERROR: frozen input files missing; run the input-staging step first.", file=sys.stderr)
        return 2

    frozen_bytes = frozen_claim_path.read_bytes()
    frozen_claim = frozen_bytes.decode("utf-8")
    frozen_sha = frozen_sha_path.read_text(encoding="utf-8").strip()
    if hashlib.sha256(frozen_bytes).hexdigest() != frozen_sha:
        print("ERROR: frozen claim file does not match its recorded SHA-256.", file=sys.stderr)
        return 2

    verdict = load_json(verdict_path)
    if verdict is not None and not isinstance(verdict, dict):
        fail("verdict.json root is not a JSON object")
        verdict = None
    if isinstance(verdict, dict):
        check_structure(verdict)
        check_provenance(verdict, frozen_claim, frozen_sha)
        check_consistency(verdict)
    check_report(report_path, verdict if isinstance(verdict, dict) else None)

    if errors:
        print("VALIDATION FAILED:", file=sys.stderr)
        for e in errors:
            print(f"  - {e}", file=sys.stderr)
        return 1

    print("VALIDATION PASSED: verdict.json and report.md satisfy the fact-check contract.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Fact-check verdict",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "claim",
    "claim_sha256",
    "verdict",
    "confidence",
    "summary",
    "evidence",
    "caveats"
  ],
  "properties": {
    "claim": {
      "type": "string",
      "minLength": 1,
      "description": "Verbatim copy of artifacts/input_claim.txt"
    },
    "claim_sha256": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}$",
      "description": "SHA-256 of the frozen input claim, copied from artifacts/input_claim.sha256"
    },
    "verdict": {
      "enum": ["supported", "refuted", "partially_supported", "unverified"]
    },
    "confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1
    },
    "summary": {
      "type": "string",
      "minLength": 1
    },
    "evidence": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["source_url", "source_title", "quote", "relation"],
        "properties": {
          "source_url": {
            "type": "string",
            "pattern": "^https?://"
          },
          "source_title": {
            "type": "string"
          },
          "quote": {
            "type": "string"
          },
          "relation": {
            "enum": ["supports", "refutes", "context"]
          }
        }
      }
    },
    "caveats": {
      "type": "array",
      "items": { "type": "string" }
    }
  }
}
